struct stat64 statbuf;
const char *filepath = "reference_file";
int dir_fd = AT_FDCWD;
int flags = AT_SYMLINK_NOFOLLOW;

// Retrieve status, relative to dir_fd
// AT_FDCWD implies relative to CWD
int status = fstatat64(
    dir_fd,
    filepath,
    &statbuf,
    flags
);

// If status == 0, status data is in statbuf
// e.g., statbuf.st_size, statbuf.st_mtime
